/* Keep the Memory tab connected to its settings without an empty divider. */
.is-memory-settings .online-setting-tabs{margin-bottom:8px;border-bottom:1px solid #ededed}
.is-memory-settings .memory-settings-fold{margin-top:0;border-top:0}

/* Let short category pages end at their content instead of filling the panel. */
.is-online-settings .online-settings-panel{flex:0 1 auto;min-height:0;padding-bottom:0}
.is-online-settings .online-setting-section:not(.memory-page){padding-bottom:0}
.is-online-settings .more-page{padding-bottom:0}
.is-online-settings .online-setting-tabs{margin-bottom:0}
.is-memory-settings .online-setting-tabs{margin-bottom:8px}
.is-online-settings .lore-character-card{margin-top:0}
.is-online-settings .more-page>.more-preference-card:first-of-type{margin-top:0}
.is-world-settings .lore-character-card{border-top:0}
.is-online-settings .more-page>.more-preference-card:first-of-type{border-top:0}
.is-online-settings .lore-character-card .avatar{overflow:hidden;border-radius:50%}
.is-online-settings .lore-character-card .avatar img{display:block;width:100%;height:100%;border-radius:50%;object-fit:cover;filter:none}
.role-worldbook-add-entry{display:flex;align-items:center;gap:3px;flex:none;padding:5px 0;border-bottom:1px solid #ddd;background:transparent;color:#666;font-size:9px;white-space:nowrap}
.role-worldbook-add-entry span{font-size:14px}
.worldbook-entry-list{min-height:0;margin-top:0;overflow-y:auto;overscroll-behavior:contain;overflow-anchor:none;scrollbar-width:thin}
.worldbook-entry{position:relative;padding:11px 2px;border-bottom:1px solid #e8e8e8}
.worldbook-entry-list>.worldbook-entry:first-child{padding-top:0}
.worldbook-entry-disclosure{width:100%;min-width:0}
.worldbook-entry-disclosure>summary{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:20px;padding-right:43px;list-style:none;cursor:pointer}
.worldbook-entry-disclosure>summary::-webkit-details-marker{display:none}
.worldbook-entry-disclosure>summary>span{display:grid;gap:5px;min-width:0}
.worldbook-entry-disclosure strong{color:#555;font-size:10px;font-weight:500}
.worldbook-entry-disclosure small{color:#aaa;font-size:8px;line-height:1.5;overflow-wrap:anywhere}
.worldbook-entry-disclosure>summary>i{display:grid;width:16px;height:16px;flex:none;place-items:center;color:#999;font-size:14px;font-style:normal;line-height:1}
.worldbook-entry-disclosure>summary>i::before{content:"+"}
.worldbook-entry-disclosure[open]>summary>i::before{content:"−"}
.worldbook-entry-disclosure>p{margin:9px 0 0;color:#888;font-size:9px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}
.worldbook-entry-toggle{position:absolute;top:12px;right:2px;z-index:1;display:block;width:31px;height:18px;cursor:pointer}
.worldbook-entry-toggle input{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;cursor:pointer}
.worldbook-entry-toggle i{position:absolute;inset:0;border-radius:12px;background:#ddd;transition:background .18s;pointer-events:none}
.worldbook-entry-toggle i:after{position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:#fff;box-shadow:0 1px 3px #0002;content:"";transition:transform .18s}
.worldbook-entry-toggle input:checked+i{background:#555}
.worldbook-entry-toggle input:checked+i:after{transform:translateX(13px)}
.worldbook-entry-toggle input:focus-visible+i{outline:2px solid #999;outline-offset:3px}
.worldbook-empty{padding:18px 2px!important;color:#999;font-size:9px;text-align:left!important}
.worldbook-empty p,.worldbook-empty .worldbook-mark{display:none}
.is-world-settings .online-settings-panel{display:flex;flex:1 1 0;flex-direction:column;min-height:0;overflow:hidden;padding-bottom:0}
.is-world-settings .online-setting-section:not(.memory-page){display:flex;flex:1;flex-direction:column;min-height:0;padding-bottom:0}
.is-world-settings .lore-character-card .lore-master-switch{display:inline-flex!important;align-items:center;justify-content:center;flex:none;width:34px;height:24px;margin:0;padding:0!important;border:0;background:transparent}
.is-world-settings .worldbook-entry-list{flex:1 1 0;max-height:none}
#chatTitle{align-items:baseline}
.chat-character-name{display:inline-block;max-width:min(25vw,170px);margin-left:.25em;overflow:hidden;color:#999;font-size:.4em;font-style:italic;font-weight:400;letter-spacing:0;line-height:1;text-overflow:ellipsis;white-space:nowrap}

/* Quiet, grouped direct-message bubbles. */
.message{gap:8px;margin:12px 0;align-items:flex-end;width:100%;max-width:100%}
.conversation{margin-inline:-12px}
.message.is-grouped{margin-top:-5px}
.message .avatar{width:38px;height:38px;font-size:17px}
.message .avatar.is-group-hidden{visibility:hidden}
.message-content{gap:4px}
.message-type-text .message-content{flex:1;min-width:0;max-width:calc(100% - 92px)}
.message-type-text:not(.mine) .message-content{margin-right:46px}
.message-type-text.mine .message-content{margin-left:46px}
.bubble{padding:10px 14px;border:1px solid #e9e9e9;border-radius:15px;background:#fff;color:#494949;font-size:13px;line-height:1.7;box-shadow:none}
.mine .bubble{border-color:#eeeeee;border-radius:15px;background:#f0f0f0;color:#494949}
.bubble-translation{padding:0 4px;color:#a0a0a0;font-size:10px;line-height:1.55}
.message-bubble-line{position:relative;display:flex;align-items:flex-end;gap:7px;width:100%;min-width:0}
.message.mine .message-bubble-line{justify-content:flex-end}
.message:not(.mine) .message-bubble-line{justify-content:flex-start}
.message-time{position:static;z-index:1;flex:0 0 auto;align-self:flex-end;width:auto;margin:0 0 3px;padding:0;color:#b0b0b0;font-size:8px;letter-spacing:.1px;line-height:1;white-space:nowrap}
.message-type-text .bubble{flex-shrink:0;max-width:100%}
.message-type-text .message-delivery-anchor{flex-shrink:0;width:max-content;max-width:100%}
.mine .bubble-translation{text-align:right}
.call-summary-message{position:relative;align-self:center;width:min(86%,370px);margin:18px 0 14px;color:#555}
.call-summary-kicker{display:flex;align-items:center;gap:9px;margin-bottom:6px;color:#999}
.call-summary-kicker i{height:1px;flex:1;background:#ededed}
.call-summary-kicker span{font-family:"Snell Roundhand","Apple Chancery","URW Chancery L","Great Vibes",cursive;font-size:14px;font-style:italic;line-height:1;color:#888}
.call-summary-open{width:100%;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 2px;border-top:1px solid #ededed;border-bottom:1px solid #ededed;background:transparent;text-align:left}
.call-summary-copy{display:grid;gap:4px;min-width:0}
.call-summary-copy strong{color:#666;font-size:10px;font-weight:400}
.call-summary-copy small{overflow:hidden;color:#aaa;font-size:8px;text-overflow:ellipsis;white-space:nowrap}
.call-summary-link{flex:none;color:#888;font-size:8px}
.call-summary-link i{margin-left:3px;color:#aaa;font-size:14px;font-style:normal;vertical-align:-1px}
.call-summary-detail{padding:3px 0 2px}
.call-summary-delete{display:block;margin:12px 0 0 auto;padding:6px 0;color:#999;font-size:10px}
.call-summary-delete:hover{color:#555}
.toast.is-compact{padding:6px 14px;font-size:11px}
.call-summary-detail>small{display:block;margin-bottom:9px;color:#aaa;font-size:9px;letter-spacing:1px}
.call-summary-detail>p{margin:0;padding:13px 0;border-top:1px solid #eee;border-bottom:1px solid #eee;color:#555;font-size:13px;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere}
.call-summary-overview>small,.call-summary-transcript>header small{display:block;color:#aaa;font-size:9px;letter-spacing:1px}
.call-summary-overview>p{margin:8px 0 0;padding:11px 0 13px;border-top:1px solid #eee;border-bottom:1px solid #eee;color:#555;font-size:12px;line-height:1.85;white-space:pre-wrap;overflow-wrap:anywhere}
.call-summary-transcript{margin-top:16px}
.call-summary-transcript>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:3px}
.call-summary-transcript>header span{color:#aaa;font-size:8px;font-variant-numeric:tabular-nums}
.call-summary-transcript-list{max-height:38dvh;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin}
.call-summary-transcript-line{padding:9px 1px 10px;border-bottom:1px solid #f0f0f0}
.call-summary-transcript-line>header{display:flex;align-items:baseline;gap:10px}
.call-summary-transcript-line>header strong{color:#777;font-size:9px;font-weight:500}
.call-summary-transcript-line>header time{margin-left:auto;color:#b6b6b6;font-size:8px;font-variant-numeric:tabular-nums}
.call-summary-transcript-line>p{margin:4px 0 0;color:#555;font-size:11px;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere}
.call-summary-transcript-line.is-user>p{color:#777}
