/* Keep the app viewport fixed; only explicitly scrollable content should move. */
html,body{width:100%;height:100vh;overflow:hidden;overscroll-behavior:none}
body{position:fixed;inset:0}
.phone{height:100dvh;min-height:0;max-height:100dvh;overscroll-behavior:none}
:where(.conversation,.settings-content,.feature-page-content,.sheet,.profile-dialog,.character-list,.offline-records-list,.global-worldbook-list,.worldbook-entry-list,.quick-features,.video-call-messages,.offline-record-transcript){overscroll-behavior:contain;-webkit-overflow-scrolling:touch}
.topbar{padding-top:24px;padding-bottom:12px}
.conversation{padding-top:6px}
.settings-topbar{padding-top:24px;padding-bottom:8px}
.settings-content{padding-top:12px}
.feature-page-topbar{padding-top:24px;padding-bottom:9px}
.feature-page-content{padding-top:12px}
@media(min-width:850px){.topbar{padding-top:28px}}
@media(max-width:480px){
  .topbar{padding-top:var(--app-safe-top,env(safe-area-inset-top));padding-bottom:10px}
  .settings-topbar{padding-top:var(--app-safe-top,env(safe-area-inset-top));padding-bottom:7px}
  .settings-content{padding-top:10px}
  .feature-page-topbar{padding-top:var(--app-safe-top,env(safe-area-inset-top));padding-bottom:7px}
  .feature-page-content{padding-top:10px}
}

