/* Distinct, quiet message treatments for media and actions. */
.message-type-image:not(.message-image-description) .message-content{width:min(62vw,240px);max-width:calc(100% - 42px)}
.message-type-sticker .message-content{max-width:min(72vw,340px)}
.message-type-voice .message-content{max-width:min(82vw,360px)}
.message-type-transfer .message-content,.message-type-location .message-content{max-width:min(76vw,300px)}
.message-type-image .message-bubble-line,.message-type-sticker .message-bubble-line{align-items:flex-end}
.message-image{display:block;width:100%;max-width:100%;padding:0;overflow:hidden;border:0;border-radius:4px;background:transparent;box-shadow:none;line-height:0}
.message-image img{display:block;width:100%;height:auto;max-width:100%;max-height:320px;object-fit:contain}
/* Compact stacked photo messages in private and group chat. */
.message-type-image:has(.chat-image-stack) .message-content{width:auto;max-width:calc(100% - 36px)}
.chat-image-stack{display:flex;align-items:center;justify-content:flex-end;gap:8px;width:min(238px,calc(100vw - 112px));height:174px;padding:0;background:transparent;touch-action:pan-y;user-select:none}
.chat-image-stack-layers{position:relative;order:2;flex:0 0 146px;height:174px}
.chat-image-stack-photo{position:absolute;top:0;left:0;width:126px;height:158px;max-width:none;max-height:none;object-fit:cover;border-radius:11px;box-shadow:0 4px 12px #0002;pointer-events:none}
.chat-image-stack-photo.is-layer-0{z-index:3;transform:rotate(-1deg)}
.chat-image-stack-photo.is-layer-1{z-index:2;top:7px;left:10px;opacity:.65;transform:rotate(2deg)}
.chat-image-stack-photo.is-layer-2{z-index:1;top:14px;left:20px;opacity:.45;transform:rotate(4deg)}
.chat-image-stack-expand{order:1;flex:none;padding:8px 10px;border-radius:999px;background:#e9e9e9;color:#666;font-size:11px;white-space:nowrap}
.chat-image-grid{display:flex;flex-direction:column;align-items:stretch;gap:3px;width:min(280px,100%);max-width:100%;padding:0;text-align:left;background:transparent;touch-action:pan-y}
.chat-image-grid-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:3px;width:100%}
.chat-image-grid-row[data-columns="1"]{grid-template-columns:minmax(0,1fr)}
.chat-image-grid-row[data-columns="2"]{grid-template-columns:repeat(2,minmax(0,1fr))}
.chat-image-grid .chat-image-grid-cell{position:relative;display:block;aspect-ratio:1;min-width:0;width:100%;height:auto;margin:0;padding:0;overflow:hidden;border-radius:5px;background:#e9e9ec;line-height:0}
.chat-image-grid .chat-image-grid-row[data-columns="1"] .chat-image-grid-cell{aspect-ratio:1.85}
.chat-image-grid .chat-image-grid-cell img{display:block;width:100%;height:100%;max-width:100%;max-height:none;object-fit:cover;pointer-events:none}
.chat-image-grid-triptych{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);grid-template-rows:repeat(2,minmax(0,1fr));gap:3px;width:100%;aspect-ratio:1.55}
.chat-image-grid .chat-image-grid-triptych .chat-image-grid-cell{aspect-ratio:auto;height:100%}
.chat-image-grid-triptych .chat-image-grid-cell:first-child{grid-row:span 2}
.chat-image-scroll-spacer{flex:none;width:100%;min-height:0;pointer-events:none}
.chat-image-expanded-item{display:flex;align-items:center;gap:8px;max-width:100%}
.chat-image-stack-collapse{flex:none;padding:7px 10px;border-radius:999px;background:#e9e9e9;color:#666;font-size:11px}
.message-type-image:has(.chat-image-expanded-item) .message-content{width:min(62vw,240px)}
.chat-image-expanded-item .message-image{min-width:0}
.chat-image-batch-carousel{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;touch-action:pan-x;overscroll-behavior-x:contain}
.chat-image-batch-carousel::-webkit-scrollbar{display:none}
