.iris-keepalive-audio{display:none!important}.keepalive-card{position:relative;display:flex;align-items:center;justify-content:space-between;gap:16px;margin:8px 0 20px;padding:16px 0;border-top:1px solid #eee;border-bottom:1px solid #eee;cursor:pointer}.keepalive-copy{display:grid;gap:6px;min-width:0}.keepalive-card strong{color:#555;font-size:12px;font-weight:400}.keepalive-card small{max-width:420px;color:#999;font-size:9px;line-height:1.7}.keepalive-card input{position:absolute;opacity:0;pointer-events:none}.keepalive-switch{position:relative;flex:none;width:34px;height:19px;border-radius:12px;background:#ddd;transition:background .18s}.keepalive-switch:after{content:"";position:absolute;top:2px;left:2px;width:15px;height:15px;border-radius:50%;background:#fff;box-shadow:0 1px 3px #0002;transition:transform .18s}.keepalive-card input:checked+.keepalive-switch{background:#555}.keepalive-card input:checked+.keepalive-switch:after{transform:translateX(15px)}.keepalive-status{color:#888;font-size:9px;white-space:nowrap}.is-system-settings .keepalive-card{border-top:0}

/* Offline story composition uses Enter for line breaks and grows for multiline drafts. */
.phone:has(.conversation.is-offline-story) .composer .input-wrap,.if-story-page>.if-chat-composer .input-wrap{height:auto;min-height:40px;max-height:106px;padding:8px 12px 8px 17px}
.phone:has(.conversation.is-offline-story) .composer .input-wrap textarea,.if-story-page>.if-chat-composer .input-wrap textarea{height:auto;min-height:22px;max-height:88px;align-self:stretch;overflow-x:hidden;overflow-y:auto;white-space:pre-wrap;line-height:22px}
