/* Offline prose semantics and live reply state. */
.offline-prose-body{white-space:normal;text-indent:0}
.offline-prose-paragraph{margin:0 0 1em;text-indent:2em;white-space:pre-wrap}
.offline-prose-paragraph:last-child{margin-bottom:0}
