@media(max-width:480px){.offline-reply-status{min-height:32px;margin-bottom:2px;padding-left:3px;font-size:10px}.offline-reply-status>.avatar{width:23px;height:23px}}

/* Give speaker changes a clearer pause while keeping same-speaker continuations compact. */
.conversation.is-offline-story>.offline-prose-entry:not(.has-next-same-speaker){margin-bottom:62px}
@media(min-width:481px){.conversation.is-offline-story>.offline-prose-entry:not(.has-next-same-speaker){margin-bottom:96px}}
@media(max-width:480px){.conversation.is-offline-story>.offline-prose-entry:not(.has-next-same-speaker){margin-bottom:84px}}

/* Indent the first line of every prose paragraph; center the offline reply row. */
.offline-prose-body>.offline-prose-paragraph{text-indent:2em}
.offline-reply-status{justify-content:center;text-align:center}

.offline-prose-body>.offline-prose-paragraph{text-indent:2em!important}

/* Offline style details stay compact until opened; extra prompt sections use small horizontal tabs. */
.offline-style-fold{grid-column:1/-1;min-width:0;border-bottom:1px solid #e9e9e9;color:#999;font-size:9px;letter-spacing:.3px}
.offline-style-fold>summary{display:flex;align-items:center;justify-content:space-between;min-height:32px;padding:0 2px;cursor:pointer;list-style:none;color:#777}
.offline-style-fold>summary::-webkit-details-marker{display:none}
.offline-style-fold>summary i{position:relative;display:block;width:12px;height:12px;flex:none}
.offline-style-fold>summary i:before,.offline-style-fold>summary i:after{position:absolute;top:5px;left:2px;width:8px;height:1px;background:#999;content:""}
.offline-style-fold>summary i:after{transform:rotate(90deg);transition:transform .18s}
.offline-style-fold[open]>summary i:after{transform:rotate(0)}
.offline-style-fold>.offline-style-manager{border:0}
.offline-extra-settings{grid-column:1/-1;display:grid;gap:8px;padding:0 2px 10px;border-bottom:1px solid #e9e9e9}
.offline-extra-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));margin-bottom:3px;border-bottom:1px solid #e9e9e9}
.offline-extra-tabs button{position:relative;padding:6px 4px 7px;background:transparent;color:#aaa;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:9px;letter-spacing:.4px;white-space:nowrap}
.offline-extra-tabs button.active{color:#555}
.offline-extra-tabs button.active::after{position:absolute;right:34%;bottom:-1px;left:34%;height:1px;background:#777;content:""}
.offline-extra-pane[hidden]{display:none!important}
.offline-extra-pane{display:grid;gap:7px}
.offline-extra-fold,.offline-regex-rule{border-bottom:1px solid #eee}
.offline-extra-fold>summary,.offline-regex-rule>summary{display:flex;align-items:center;justify-content:space-between;min-height:34px;cursor:pointer;list-style:none;color:#777;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:10px;letter-spacing:.2px}
.offline-extra-fold>summary::-webkit-details-marker,.offline-regex-rule>summary::-webkit-details-marker{display:none}
.offline-extra-fold>summary i,.offline-regex-rule>summary i{position:relative;display:block;width:12px;height:12px;flex:none}
.offline-extra-fold>summary i:before,.offline-extra-fold>summary i:after,.offline-regex-rule>summary i:before,.offline-regex-rule>summary i:after{position:absolute;top:5px;left:2px;width:8px;height:1px;background:#aaa;content:""}
.offline-extra-fold>summary i:after,.offline-regex-rule>summary i:after{transform:rotate(90deg);transition:transform .18s}
.offline-extra-fold[open]>summary i:after,.offline-regex-rule[open]>summary i:after{transform:rotate(0)}
.offline-extra-fold[open],.offline-regex-rule[open]{padding-bottom:8px}
.offline-config-item,.offline-regex-item{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px;padding:7px 8px;border:1px solid #ece9ec;border-radius:11px;background:rgba(255,255,255,.78)}
.offline-config-item>.offline-extra-fold,.offline-regex-item>.offline-regex-rule{min-width:0;border:0}
.offline-regex-item>.offline-regex-rule{width:100%;align-self:start}
.offline-config-item:has(>details[open]),.offline-regex-item:has(>.offline-regex-rule[open]){grid-template-columns:minmax(0,1fr)}
.offline-config-item:has(>details[open])>.offline-extra-fold,.offline-regex-item:has(>.offline-regex-rule[open])>.offline-regex-rule{grid-column:1}
.offline-config-item:has(>details[open])>.offline-config-actions,.offline-regex-item:has(>.offline-regex-rule[open])>.offline-config-actions{grid-column:1;justify-self:end;margin-top:0}
.offline-config-actions{display:flex;align-items:center;gap:5px;align-self:center;margin-top:0}
.offline-config-switch{position:relative;display:inline-flex;width:42px;height:24px;margin:0;flex:none;cursor:pointer}
.offline-config-switch input{position:absolute;width:1px;height:1px;opacity:0}
.offline-config-switch i{position:absolute;inset:0;border-radius:999px;background:#ddd;transition:background .18s}
.offline-config-switch i:after{position:absolute;top:2px;left:2px;width:20px;height:20px;border-radius:50%;background:white;box-shadow:0 1px 3px #0002;content:"";transition:transform .18s}
.offline-config-switch input:checked+i{background:#111}
.offline-config-switch input:checked+i:after{transform:translateX(18px)}
.offline-config-switch input:focus-visible+i{outline:2px solid #aaa;outline-offset:2px}
.offline-config-actions>.offline-extra-remove{display:inline-flex;align-items:center;justify-content:center;width:42px;height:24px;margin:0;padding:0;border:0;border-radius:999px;background:#f4f3f4;color:#999;font-size:9px;line-height:1}
.offline-regex-item>.offline-config-actions>[data-regex-save]{display:none}
.offline-regex-item>.offline-config-actions>[data-regex-cancel]{display:none}
.offline-regex-item:has(>.offline-regex-rule[open])>.offline-config-actions>[data-regex-cancel],.offline-regex-item:has(>.offline-regex-rule[open])>.offline-config-actions>[data-regex-save]{display:inline-flex;align-items:center;justify-content:center;min-width:48px;height:24px;margin:0;padding:0 9px;border:1px solid #e4e1e4;border-radius:999px;background:#fff;color:#777;font-size:9px;line-height:1}
.offline-config-actions>.offline-extra-remove:active{background:#eae8ea;color:#666}
.offline-extra-fold>summary,.offline-regex-rule>summary{min-height:36px}
.offline-draft-cot-content{max-height:360px;overflow:auto;padding:6px 3px;color:#666;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:9px;line-height:1.7;white-space:pre-wrap;scrollbar-width:thin}
.offline-extra-field{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:6px;color:#999;font-size:8px;letter-spacing:.3px}.offline-extra-field>span{color:#999;font-size:8px;letter-spacing:.3px}
.offline-extra-name{display:grid;grid-column:1/-1;gap:5px;color:#999;font-size:9px;letter-spacing:.2px}
.offline-extra-name input{width:100%;min-width:0;padding:5px 2px;border:0;border-bottom:1px solid #eee;border-radius:0;background:transparent;color:#555;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:11px;outline:none}
.offline-extra-name input::placeholder{color:#bbb}
.offline-extra-field textarea{grid-column:1/-1;width:100%;min-height:116px;max-height:45dvh;padding:5px 2px 8px;border:0;border-radius:0;background:repeating-linear-gradient(to bottom,#fff 0,#fff 25px,#f0f0f0 25px,#f0f0f0 26px);color:#555;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:11px;line-height:26px;resize:vertical;scrollbar-width:thin}
.offline-extra-field textarea::placeholder{color:#bbb;font-size:10px}
.offline-extra-add,.offline-extra-remove{justify-self:start;padding:5px 0;border-bottom:1px solid #ddd;background:transparent;color:#888;font-size:9px;letter-spacing:.1px}
.offline-extra-remove{justify-self:end;padding:2px 0;color:#aaa;font-size:8px}
.offline-extra-field footer,.offline-regex-rule footer{display:flex;align-items:center;justify-content:flex-end;gap:14px;grid-column:1/-1}
.offline-extra-save{padding:4px 10px;border:1px solid #e4e1e4;border-radius:999px;background:#fff;color:#777;font-size:9px;letter-spacing:.2px}
.offline-extra-cancel{padding:4px 10px;border:1px solid #eee;border-radius:999px;background:#fafafa;color:#999;font-size:9px;letter-spacing:.2px}
.offline-extra-save:active{background:#f5f3f5;color:#444}
.offline-extra-cancel:active{background:#f5f3f5;color:#666}
.offline-extra-add:active,.offline-extra-remove:active{color:#555}
.offline-extra-pane[data-offline-extra-pane="regex"]>.offline-extra-add{justify-self:stretch;padding:7px 10px;border:1px dashed #e7e4e7;border-radius:9px;background:rgba(255,255,255,.55);color:#999;text-align:center}
.offline-extra-pane[data-offline-extra-pane="regex"]>.offline-extra-add:active{background:#f7f6f7}
.offline-regex-rule{display:block;padding:0 5px;border:0;border-bottom:0;border-radius:0;background:transparent}
.offline-regex-rule-content{display:grid;gap:8px;padding:4px 2px 1px}
.offline-regex-rule-content>header{display:grid;grid-template-columns:minmax(0,1fr) minmax(140px,1fr);align-items:end;gap:8px}
.offline-regex-rule-content label{display:grid;gap:5px;color:#999;font-size:9px;letter-spacing:.2px}
.offline-regex-scopes{display:flex;align-items:center;flex-wrap:wrap;gap:4px;min-width:0;margin:0;padding:0;border:0;color:#999}
.offline-regex-scopes legend{width:100%;padding:0 0 3px;color:#999;font-size:9px;letter-spacing:.2px}
.offline-regex-scopes label{display:flex;align-items:center;gap:0;padding:5px 8px;border:1px solid #efedef;border-radius:999px;background:#fff;color:#999;font-size:9px;white-space:nowrap;cursor:pointer}
.offline-regex-scopes label:has(input:checked){border-color:#e1dee1;background:#f5f4f5;color:#666}
.offline-regex-scopes input[type="checkbox"]{position:absolute;width:1px;min-height:1px;height:1px;opacity:0}
.offline-regex-rule input:not([type="checkbox"]),.offline-regex-rule select{width:100%;min-height:32px;padding:6px 9px;border:1px solid #efedef;border-radius:8px;background:#fff;color:#666;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:10px}
.offline-regex-rule textarea{width:100%;min-height:42px;max-height:150px;padding:7px 9px;border:1px solid #efedef;border-radius:8px;background:#fff;color:#555;font-family:ui-monospace,SFMono-Regular,monospace;font-size:9px;line-height:1.6;resize:vertical;overflow-wrap:anywhere}
.offline-regex-rule-content>label:nth-of-type(2) textarea{min-height:34px}
.offline-regex-rule textarea::placeholder{color:#bbb;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:9px}
.offline-regex-rule-content footer{display:flex;align-items:center;justify-content:flex-end;gap:10px;padding-top:1px}
.offline-regex-rule-content .offline-extra-save{min-width:66px}
.offline-regex-item .offline-config-switch{align-self:start;margin-top:0}
.offline-regex-lanes{display:flex;align-items:center;gap:6px;margin:0;padding:7px 0 0;border:0;border-top:1px solid #f0eef0}
.offline-regex-lanes legend{width:100%;padding:0 0 3px;color:#999;font-size:9px}
.offline-regex-test{border-top:1px solid #f0eef0;padding-top:6px}
.offline-regex-test>summary{display:flex;align-items:center;min-height:27px;color:#888;font-size:10px;cursor:pointer;list-style:none}
.offline-regex-test>summary::-webkit-details-marker{display:none}
.offline-regex-test>div{display:grid;gap:7px;padding:4px 0}
.offline-regex-test textarea{width:100%;min-height:54px;padding:7px 9px;border:1px solid #efedef;border-radius:8px;background:#fff;color:#555;font:10px/1.6 ui-monospace,SFMono-Regular,monospace;resize:vertical}
.offline-regex-test-options{display:flex;align-items:center;gap:6px}
.offline-regex-test-options select{min-height:30px;padding:4px 7px;border:1px solid #efedef;border-radius:8px;background:#fff;color:#777;font-size:10px}
.offline-regex-test-options button{min-height:30px;padding:0 11px;border:1px solid #e9e6e9;border-radius:8px;background:#f8f7f8;color:#666;font-size:10px}
.offline-regex-test-result{display:grid;grid-template-columns:1fr;gap:4px;max-height:220px;overflow:auto;padding:8px;border-radius:8px;background:#f7f6f7}
.offline-regex-test-result small{color:#999;font-size:9px}
.offline-regex-test-result pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;color:#666;font:10px/1.55 ui-monospace,SFMono-Regular,monospace}
.offline-regex-order{margin:0 0 6px;padding:8px 10px;border-radius:9px;background:#f7f6f7;color:#929092;font-size:9px;line-height:1.65}
.offline-stage-memory-panel{display:grid;gap:10px;padding:12px}
.offline-stage-memory-panel>header{display:grid;gap:4px;margin-bottom:2px}
.offline-stage-memory-panel>header strong{color:#676368;font-size:13px;font-weight:500}
.offline-stage-memory-panel>header small,.offline-stage-memory-footnote{color:#a09ba0;font-size:10px;line-height:1.6}
.offline-stage-memory-status{margin:0;padding:9px 11px;border-radius:9px;background:#faf5f2;color:#a37b68;font-size:10px;line-height:1.6}
.offline-stage-memory-card{padding:0 10px 9px;border:1px solid #ece9ec;border-radius:11px;background:rgba(255,255,255,.82)}
.offline-stage-memory-card.is-stale{border-color:#eadbd5;background:#fffaf8}
.offline-stage-memory-card details>summary{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:40px;color:#777;font-size:10px;cursor:pointer;list-style:none}
.offline-stage-memory-card details>summary::-webkit-details-marker{display:none}
.offline-stage-memory-card details>summary small{flex:none;color:#aaa;font-size:9px}
.offline-stage-memory-card textarea{width:100%;min-height:90px;padding:9px 10px;border:1px solid #efedef;border-radius:9px;background:#fff;color:#666;font:11px/1.65 -apple-system,BlinkMacSystemFont,sans-serif;resize:vertical}
.offline-stage-memory-card footer{display:flex;justify-content:flex-end;gap:7px;padding-top:8px}
.offline-stage-memory-card footer button{min-height:30px;padding:0 11px;border:1px solid #e9e6e9;border-radius:8px;background:#f8f7f8;color:#777;font-size:10px}
.offline-stage-memory-card footer button:disabled{opacity:.45}
.offline-stage-memory-empty{display:grid;gap:5px;padding:22px 12px;border:1px dashed #e9e6e9;border-radius:11px;text-align:center;color:#aaa;font-size:10px}
