.offline-stage-memory-footnote{margin:2px 0 0}

.offline-generation-diagnostics .offline-extra-field{display:block}
.offline-generation-diagnostics .offline-extra-field>details{margin-top:10px}

/* Raw streamed blocks stay plain until their comment or paragraph is complete. */
.offline-prose-body>.offline-streaming-plain{white-space:pre-wrap;overflow-wrap:anywhere}

/* Indent each user-entered line; blank lines retain a paragraph gap. */
.offline-prose-entry.is-user .offline-user-paragraph{margin:0 0 1em}
.offline-prose-entry.is-user .offline-user-paragraph:last-child{margin-bottom:0}
.offline-prose-entry.is-user .offline-user-paragraph>.offline-prose-paragraph{margin:0;text-indent:2em!important}

/* Show the requirements save action to the left of its enable switch when expanded. */
.offline-config-item>.offline-config-actions>[data-offline-extra-save="requirements"]{display:none}
.offline-config-item:has(>.offline-extra-fold[open])>.offline-config-actions>[data-offline-extra-save="requirements"]{display:inline-flex;align-items:center;justify-content:center;min-width:48px;height:24px;margin:0;padding:0 9px;line-height:1}

/* Editable draft COT uses the same expanded save action as other requirements. */
textarea.offline-draft-cot-content{display:block;width:100%;min-height:280px;border:0;border-radius:0;background:transparent;resize:vertical;outline:none}
.offline-config-item>.offline-config-actions>[data-mini-theater-prompt-save]{display:none}
.offline-config-item:has(>.offline-extra-fold[open])>.offline-config-actions>[data-mini-theater-prompt-save]{display:inline-flex;align-items:center;justify-content:center;min-width:48px;height:24px;margin:0;padding:0 9px;line-height:1}
.offline-config-item>.offline-config-actions>[data-draft-cot-save]{display:none}
.offline-config-item:has(>.offline-extra-fold[open])>.offline-config-actions>[data-draft-cot-save]{display:inline-flex;align-items:center;justify-content:center;min-width:48px;height:24px;margin:0;padding:0 9px;line-height:1}

/* Offline interactive side stories are isolated and folded below their main reply. */
.offline-mini-theater{width:100%;min-width:0;margin-top:14px;text-indent:0;color:#777;font:11px/1.7 "Songti SC",serif}
.offline-mini-theater>summary{display:flex;align-items:center;gap:6px;list-style:none;cursor:pointer;padding:4px 0;touch-action:manipulation}
.offline-mini-theater>summary::-webkit-details-marker{display:none}
.offline-mini-theater>summary::before{content:'▸'}
.offline-mini-theater[open]>summary::before{content:'▾'}
.offline-mini-theater-frame{display:block;width:100%;max-width:100%;height:48px;margin-top:8px;border:0;background:transparent;overflow:hidden;pointer-events:auto;touch-action:auto;-webkit-overflow-scrolling:touch}
.offline-mini-theater-status{margin:6px 0 0;color:#9a5b4a;font:12px/1.5 "Songti SC",serif}

