/* Marketplace, tuned to Iris's quiet monochrome phone UI. */
.iris-market{--market-ink:#333;--market-muted:#999;--market-line:#ececec;--market-soft:#f5f5f5;--market-radius:12px;width:min(100%,520px);max-width:520px;min-height:100%;margin:0 auto;padding:2px 0 28px;color:var(--market-ink);font-family:inherit;font-size:12px;line-height:1.6}
.market-welcome{padding:8px 0 18px}
.market-welcome>small,.market-section header small,.market-wallet>small{color:#aaa;font-family:Georgia,serif;font-size:8px;letter-spacing:1.8px}
.market-welcome h1{display:block;margin:8px 0 7px;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:27px;font-weight:400;letter-spacing:.04em;line-height:1.45}
.market-welcome p{margin:0;color:#999;font-size:9px;letter-spacing:.2px}
.market-search{height:42px;margin:2px 0 13px;padding:0 14px;border:1px solid #e9e9e9;border-radius:24px;background:#f4f4f4}
.market-search>span{display:grid;width:19px;height:19px;place-items:center;color:#888;font-size:18px}
.market-search input{font-size:11px;color:#444}
.market-search input::placeholder{color:#aaa}
.market-search button{padding:5px 1px;color:#666;font-size:10px}
.market-categories,.market-category-pills{gap:7px;padding:1px 0 16px}
.market-categories button,.market-category-pills button{padding:6px 11px;border:1px solid #e9e9e9;border-radius:18px;background:#fff;color:#777;font-size:9px;transition:background .18s,color .18s,border-color .18s}
.market-categories button:active,.market-category-pills button:active,.market-category-pills button.is-active{border-color:#444;background:#444;color:#fff}
.market-section{margin:16px 0 23px}
.market-section>header{align-items:center;margin-bottom:11px}
.market-section header small{font-size:7px;letter-spacing:1.5px}
.market-section h2{margin:2px 0 0;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:17px;font-weight:400;letter-spacing:.04em}
.market-section header>button{color:#888;font-size:9px}
.market-grid{gap:17px 12px}
.market-product{gap:0;overflow:hidden;background:#fff;text-align:left}
.market-product-art{aspect-ratio:1/1;border-radius:8px;background:#f2f2f2;color:#555;isolation:isolate}
.market-product-art::after{position:absolute;inset:0;z-index:-1;background:linear-gradient(145deg,#f6f6f6,#ececec);content:""}
.market-product-art[data-market-category="鲜花"]::after,.market-product-art[data-market-category="食品"]::after{background:linear-gradient(145deg,#f5f5f5,#e9e9e9)}
.market-product-art[data-market-category="服装"]::after,.market-product-art[data-market-category="鞋包"]::after{background:linear-gradient(145deg,#f1f1f1,#e7e7e7)}
.market-product-art[data-market-category="数码"]::after,.market-product-art[data-market-category="家居"]::after{background:linear-gradient(145deg,#f6f6f6,#eaeaea)}
.market-product-art>span{display:grid;width:60%;height:60%;place-items:center;color:#757575;text-shadow:none}
.market-product-art>span svg{width:52%;height:52%;overflow:visible;stroke:#777;stroke-width:1.15}
.market-product-art>i{right:8px;bottom:7px;color:#999;font-family:inherit;font-size:7px;font-style:normal;letter-spacing:1px}
.market-product-art.is-large{aspect-ratio:1.14/1;margin:0 0 18px;border-radius:10px}
.market-product-art.is-large>span{width:64%;height:64%}
.market-product-copy{gap:2px;padding:7px 1px 9px}
.market-product-copy strong{font-size:11px;font-weight:400;color:#393939}
.market-product-copy small{color:#a0a0a0;font-size:8px}
.market-product-copy b{margin-top:3px;color:#333;font-family:Georgia,serif;font-size:12px;font-weight:500;font-variant-numeric:tabular-nums}
.market-shops{grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border-top:1px solid #eee;border-bottom:1px solid #eee}
.market-shops button{gap:5px;padding:11px 2px;border:0;border-right:1px solid #f0f0f0;background:#fff}
.market-shops button:last-child{border-right:0}
.market-shops i{width:31px;height:31px;border:1px solid #ededed;border-radius:50%;background:#f8f8f8;color:#777;font-size:12px}
.market-shops strong{font-size:8px;font-weight:400;color:#555}
.market-shops small{font-size:7px;color:#aaa}
.market-recent{gap:8px;padding-bottom:3px}
.market-recent span{padding:6px 0;border-bottom:1px solid #e8e8e8;color:#777;font-size:9px}
.market-nav{position:sticky;bottom:max(8px,env(safe-area-inset-bottom));margin:20px 0 0;padding:5px;border:1px solid #e7e7e7;border-radius:30px;background:#fafafa;box-shadow:0 4px 18px #00000008}
.market-nav button{flex:1;min-width:0;padding:9px 3px;border-radius:22px;color:#999;font-size:9px;transition:background .18s,color .18s}
.market-nav button.is-active{background:#e9e9e9;color:#222}
.market-subhead{min-height:45px;margin:0 0 11px;border-color:#ededed}
.market-subhead button{min-width:32px;padding:8px 3px;color:#777;font-size:11px}
.market-subhead h2{font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:17px;font-weight:400;letter-spacing:.04em}
.market-subhead small{color:#999;font-size:9px}
.market-category-pills{margin:0 0 9px;padding-bottom:13px}
.market-detail{padding:0 0 96px}
.market-detail>small{color:#999;font-size:9px;letter-spacing:.4px}
.market-detail h1{margin:6px 0 2px;font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:21px;font-weight:400;letter-spacing:.04em}
.market-detail-price{margin:1px 0 12px;color:#303030;font-size:21px;font-variant-numeric:tabular-nums}
.market-detail>p{color:#777;font-size:11px;line-height:1.85}
.market-options{gap:9px;margin:14px 0;padding:13px 0;border-color:#eee}
.market-options>strong,.market-reviews h3{font-size:10px;font-weight:500;color:#555}
.market-options label{gap:9px;color:#666;font-size:10px}
.market-options input{accent-color:#444}
.market-shipping-note{color:#777}
.market-favorite{padding:7px 0;color:#666;font-size:10px}
.market-reviews{margin-top:17px}
.market-reviews h3{margin-bottom:4px}
.market-reviews p{margin:0;padding:10px 0;border-color:#eee;color:#666;font-size:10px;line-height:1.7}
.market-reviews p b{color:#666;font-size:10px}
.market-buybar,.market-checkoutbar{gap:8px;padding:10px 0 max(10px,env(safe-area-inset-bottom));border-color:#ededed;background:#fff}
.market-buybar button,.market-checkoutbar button{min-height:40px;padding:9px 7px;border:1px solid #e1e1e1;border-radius:22px;background:#fff;color:#555;font-size:10px}
.market-buybar .is-primary,.market-checkoutbar .is-primary{border-color:#555;background:#555;color:#fff}
.market-cart-row{grid-template-columns:18px 70px minmax(0,1fr);gap:9px;padding:13px 0;border-color:#eee}
.market-cart-row .market-product-art{border-radius:7px}
.market-cart-row>div{gap:4px}
.market-cart-row strong{font-size:11px;font-weight:400;color:#444}
.market-cart-row small{font-size:9px;color:#999}
.market-cart-row b{font-size:12px;font-variant-numeric:tabular-nums}
.market-cart-row>input{accent-color:#444}
.market-quantity{gap:8px;font-size:9px}
.market-quantity button{min-width:24px;min-height:24px;border:1px solid #e7e7e7;border-radius:50%;background:#fff;color:#555}
.market-quantity button:last-child{margin-left:0;border:0;border-radius:0;color:#999}
.market-checkoutbar{margin-top:14px}
.market-checkoutbar>span{color:#777;font-size:10px}
.market-checkoutbar>span b{color:#333;font-size:15px;font-variant-numeric:tabular-nums}
.market-panel{gap:9px;margin:13px 0;padding:13px 0;border-color:#ededed}
.market-panel h3{font-size:11px;font-weight:400;color:#555;letter-spacing:.2px}
.market-panel p,.market-panel small{font-size:9px;color:#999}
.market-panel select,.market-panel textarea,.market-address-form input,.market-review-form textarea{padding:10px 12px;border:1px solid #e9e9e9;border-radius:10px;background:#f8f8f8;color:#555;font-size:10px}
.market-panel textarea,.market-review-form textarea{min-height:72px}
.market-role-pay button{min-height:36px;padding:8px 14px;border-color:#e1e1e1;border-radius:20px;background:#fff;color:#555;font-size:9px}
.market-primary-full,.market-secondary-full{min-height:42px;margin:12px 0;border:1px solid #555;border-radius:24px;background:#555;color:#fff;font-size:10px}
.market-secondary-full{border-color:#e2e2e2;background:#fff;color:#666}
.market-order{margin:12px 0;padding:12px 0;border:0;border-top:1px solid #e9e9e9;border-bottom:1px solid #e9e9e9}
.market-order header,.market-order footer{font-size:9px;color:#999}
.market-order header b{color:#555;font-weight:400}
.market-order p{margin:10px 0;color:#555;font-size:10px}
.market-order footer{padding-top:9px;border-color:#eee;font-size:8px}
.market-order footer button{color:#666}
.market-order-tabs{justify-content:flex-start;gap:17px;border-color:#eee}
.market-order-tabs button{position:relative;padding:10px 1px;color:#999;font-size:9px}
.market-order-tabs button:focus,.market-order-tabs button:active{color:#333}
.market-receipt{margin:16px 0;padding:16px 14px;border:1px dashed #d5d5d5;border-radius:4px;background:repeating-linear-gradient(0deg,#fff 0,#fff 27px,#fafafa 27px,#fafafa 28px);color:#555}
.market-receipt>small{color:#aaa;font-size:7px;letter-spacing:1.8px}
.market-receipt h2{font-family:"Songti SC","Noto Serif CJK SC",serif;font-size:16px;color:#444}
.market-receipt p{color:#666;font-size:9px}
.market-receipt p b{color:#444;font-variant-numeric:tabular-nums}
.market-receipt hr{border-color:#ddd}
.market-logistics{gap:10px;padding:7px 0}
.market-logistics i{width:8px;height:8px;border:1px solid #aaa;background:#fff}
.market-logistics b{font-size:10px;font-weight:400;color:#555}
.market-logistics small{font-size:8px;color:#aaa}
.market-role-decision{padding:12px;border:1px solid #ededed;border-radius:10px;background:#fafafa}
.market-role-wallet-wrap{border-color:#ededed}
.market-wallet-toggle{border-color:#e5e5e5!important}
.market-wallet-toggle svg{stroke:#666}
.market-role-wallet>strong{font-size:20px;color:#333}
.market-role-wallet>p b.is-credit{color:#555}
.market-review-form{gap:9px;margin:15px 0;padding-top:13px;border-color:#eee}
.market-review-form h3{font-size:11px;font-weight:400;color:#555}
.market-review-form select{min-height:38px;padding:8px 10px;border:1px solid #e9e9e9;border-radius:9px;background:#f8f8f8;color:#555;font-size:10px}
.market-review-form button,.market-address-form button{min-height:36px;padding:8px 14px;border-radius:20px;background:#555;color:#fff;font-size:9px}
.market-wallet{gap:8px;padding:15px 0;border:0;border-top:1px solid #eee;border-bottom:1px solid #eee;background:#fff}
.market-wallet strong{font-size:24px;color:#333;font-variant-numeric:tabular-nums}
.market-wallet button{padding:5px 0;border-color:#ddd;color:#777}
.market-wallet p{font-size:8px;color:#aaa}
.market-mine-links{gap:0 16px;margin:12px 0}
.market-mine-links button{padding:13px 1px;border-color:#eee;color:#666;font-size:10px}
.market-address{padding:13px 0;border-color:#eee}
.market-address strong{font-size:11px;font-weight:400;color:#444}
.market-address p{font-size:9px;color:#888}
.market-address button{margin-right:15px;padding:7px 0;color:#777;font-size:9px}
.market-address-form{gap:10px;padding-top:15px;border-top:1px solid #eee}
.market-address-form h3{font-size:11px;font-weight:400;color:#555}
.market-address-form label{font-size:9px;color:#888}
.market-address-form input[type="checkbox"]{width:auto;margin-right:6px;accent-color:#555}
.market-address-page{padding-top:2px}
.market-address-list-heading{display:flex;align-items:center;gap:7px;margin:3px 0 10px;color:#555;font-size:11px}
.market-address-list-heading small{color:#aaa;font-size:9px;font-variant-numeric:tabular-nums}
.market-address-list{display:grid;gap:9px}
.market-address-card{padding:13px 13px 3px;border:1px solid #e9e9e9;border-radius:13px;background:#fff}
.market-address-card>header{display:flex;align-items:center;gap:10px;min-width:0}
.market-address-recipient{display:flex;align-items:baseline;flex-wrap:wrap;gap:5px 10px;min-width:0;flex:1}
.market-address-recipient>strong{color:#333;font-size:12px;font-weight:500;overflow-wrap:anywhere}
.market-address-recipient>span{color:#888;font-size:10px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.market-address-default-tag{flex:none;padding:3px 7px;border-radius:10px;background:#333;color:#fff;font-size:8px;line-height:1.2}
.market-address-destination{display:flex;align-items:flex-start;gap:8px;margin:11px 0 12px;color:#666;font-size:10px;line-height:1.7}
.market-address-destination svg{width:14px;height:14px;flex:none;margin-top:2px;fill:none;stroke:#999;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.market-address-destination span{min-width:0;overflow-wrap:anywhere}
.market-address-card>footer{display:flex;align-items:center;gap:15px;min-height:36px;padding:2px 0;border-top:1px solid #f0f0f0}
.market-address-card>footer button{padding:6px 0;background:transparent;color:#666;font-size:9px}
.market-address-card>footer button.is-muted{margin-left:auto;color:#aaa}
.market-address-empty{display:grid;justify-items:center;gap:7px;padding:22px 14px 20px;border:1px dashed #e6e6e6;border-radius:13px;color:#777;text-align:center}
.market-address-empty-icon,.market-address-form-icon{display:grid;width:32px;height:32px;place-items:center;border:1px solid #eee;border-radius:50%;color:#777}
.market-address-empty-icon svg,.market-address-form-icon svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.45;stroke-linecap:round;stroke-linejoin:round}
.market-address-empty>strong{font-size:11px;font-weight:400}
.market-address-empty>small{max-width:245px;color:#aaa;font-size:9px;line-height:1.6}
.market-address-page>.market-address-form{display:grid;gap:13px;margin-top:16px;padding:14px;border:1px solid #e9e9e9;border-radius:14px;background:#fff}
.market-address-form>header{display:flex;align-items:center;gap:9px;min-width:0}
.market-address-form>header>span:nth-child(2){display:grid;gap:3px;min-width:0;flex:1}
.market-address-form>header strong{color:#444;font-size:11px;font-weight:500}
.market-address-form>header small{color:#aaa;font-size:8px}
.market-address-form>.market-address-form-icon{flex:none}
.market-address-form .market-address-cancel{padding:5px 0;background:transparent;color:#999;font-size:9px}
.market-address-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px 9px}
.market-address-fields label{display:grid;gap:6px;min-width:0;color:#777;font-size:9px}
.market-address-fields label.is-wide{grid-column:1/-1}
.market-address-fields input{height:38px;min-width:0;padding:0 10px!important;border:1px solid #e8e8e8!important;border-radius:8px!important;background:#fafafa!important;color:#444!important;font-size:10px!important}
.market-address-fields input::placeholder{color:#bbb}
.market-address-default-choice{display:flex;align-items:center;gap:9px;min-width:0;padding:10px 0;border-top:1px solid #f0f0f0}
.market-address-form .market-address-default-choice>input{width:16px;height:16px;flex:none;margin:0;accent-color:#333}
.market-address-default-choice>span{display:grid;gap:3px}
.market-address-default-choice strong{color:#555;font-size:9px;font-weight:400}
