/* A quiet editorial timeline: one node and one card per release. */
.release-notice-dialog{width:min(420px,calc(100vw - 32px));max-height:min(86dvh,780px);margin:auto;padding:0;overflow:hidden;border:1px solid #e5e5e5;border-radius:22px;background:#fdfdfd;color:#555;box-shadow:0 24px 90px #00000018,0 3px 12px #00000005;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
