#irisReleaseNotice .release-notice-close:hover{color:#555}
#irisReleaseNotice .release-notice-close:focus,#irisReleaseNotice .release-notice-close:focus-visible{outline:none}
#irisReleaseNotice .release-notice-close:focus-visible{outline:1px solid #888;outline-offset:2px;border-radius:4px}
.release-notice-heading{flex-shrink:0;padding:25px 0 26px}
