.release-timeline{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;margin:0 -5px 0 -6px;padding:4px 5px 20px 6px;list-style:none;scrollbar-width:thin;scrollbar-color:#ddd transparent}
.release-timeline-entry{position:relative;padding:0 0 20px 23px}
