.release-author-note{margin-top:19px;padding-top:15px;border-top:1px solid #eee}.release-author-note h3{margin:0 0 9px;color:#555;font-size:11px;font-weight:500;letter-spacing:1px}.release-author-note p{margin:8px 0 0;color:#777;font-size:11px;line-height:1.95;overflow-wrap:anywhere}.release-author-note strong{color:#b13e38;font-weight:600}
.release-notice-card>footer{margin:0 -27px;padding:17px 27px 20px;border-top:1px solid #ededed;background:#fdfdfd}
.release-notice-card>footer small{font-size:8px;line-height:1.7;color:#aaa;letter-spacing:.2px}
.release-notice-card>footer button{display:flex;align-items:center;justify-content:space-between;gap:22px;flex:none;min-width:103px;padding:11px 15px;border:1px solid #ddd;border-radius:8px;background:#fff;color:#666;font-size:10px;box-shadow:0 2px 3px #00000002;transition:border-color .18s,background .18s}
