@media(max-width:360px){.release-notice-card{padding:22px 20px 0}.release-notice-heading{padding:20px 0}.release-timeline-entry{padding-left:20px}.release-timeline-entry>details>summary{padding:15px 14px}.release-version-content{margin-inline:14px}.release-notice-card>footer{margin-inline:-20px;padding-inline:20px}.release-version-line strong{font-size:20px}}

