.novel-screen-cast article{display:flex;align-items:center;gap:12px;min-width:0}.novel-screen-cast .avatar{width:36px;height:36px;border-width:1px;font-size:14px;overflow:hidden}.novel-screen-cast .avatar img{width:100%;height:100%;object-fit:cover}
