/* Shared function-menu layout: home, online/offline composer and IF stories. */
body[data-function-layout="horizontal"] :is(.quick-features,.if-story-tools-menu):not([hidden]){display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px 8px;box-sizing:border-box;width:min(360px,calc(100vw - 48px));max-width:none;max-height:60dvh;overflow-y:auto;padding:18px 12px;background:var(--surface,#fff)!important;border:1px solid #e9e9e9!important;border-radius:20px;box-shadow:0 8px 32px #00000016!important;align-items:start}
body[data-function-layout="horizontal"] .quick-action-row{display:contents}
body[data-function-layout="horizontal"] :is(.quick-features .quick-item,.quick-features .quick-action-item,.if-world .if-chat-composer .if-story-tool){display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:7px;min-width:0;width:100%;padding:0;border:0;background:transparent;color:#555;font-size:10px;line-height:1.35;text-align:center;white-space:normal}
body[data-function-layout="horizontal"] :is(.quick-item,.quick-action-item)>.quick-icon{order:-1;display:grid;place-items:center;flex:none;width:38px;height:38px;padding:0;border-radius:50%;background:#f0f0f0}
body[data-function-layout="horizontal"] :is(.quick-item,.quick-action-item)>.quick-icon svg{box-sizing:border-box;width:38px;height:38px;padding:10px}
body[data-function-layout="horizontal"] :is(.dock-feature-menu .quick-item>span:first-child,.if-story-tool-label){padding:0;background:transparent;box-shadow:none;overflow-wrap:anywhere}
body[data-function-layout="horizontal"] .dock-feature-menu .function-language-switch{grid-column:1/-1;justify-self:end;margin-top:0}
body[data-function-layout="horizontal"] .if-story-tool-icon{flex:none}

/* Keep vertical labels beside their icons even when the settings capsule widens the menu. */
body:not([data-function-layout="horizontal"]) .dock-feature-menu .quick-item{justify-content:flex-end;gap:8px}

/* Offline tool geometry: identical layout boxes; backgrounds are separate from SVGs. */
body #quickFeatures:has(>[data-quick="退出"])>.quick-item{margin:0;align-self:start;align-items:center;line-height:1.35}
body #quickFeatures:has(>[data-quick="退出"])>.quick-item>.quick-icon{position:relative;display:grid;place-items:center;box-sizing:border-box;flex:none;width:38px;height:38px;min-height:38px;margin:0;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;line-height:0;isolation:isolate}
body #quickFeatures:has(>[data-quick="退出"])>.quick-item>.quick-icon::before{content:"";position:absolute;inset:0;border-radius:50%;background:#f0f0f0;z-index:-1}
body #quickFeatures:has(>[data-quick="退出"])>.quick-exit>.quick-icon::before{inset:2px;background:#333}
body #quickFeatures:has(>[data-quick="退出"])>.quick-item>.quick-icon svg{display:block;box-sizing:border-box;flex:none;width:18px;height:18px;min-height:0;max-height:none;margin:0;padding:0;border:0;border-radius:0;background:transparent!important;box-shadow:none}
body #quickFeatures:has(>[data-quick="退出"])>.quick-exit>.quick-icon svg{color:#fff}
body[data-function-layout="horizontal"] #quickFeatures:has(>[data-quick="退出"])>.quick-item{display:grid;grid-template-rows:38px 24px;justify-items:center;align-items:center;align-content:start;gap:7px;padding:0;min-height:0}
body[data-function-layout="horizontal"] #quickFeatures:has(>[data-quick="退出"])>.quick-item>span:last-child{box-sizing:border-box;display:flex;align-items:center;justify-content:center;height:24px;min-height:24px;margin:0;padding:5px 8px;line-height:14px}

